/**
 * 海龟汤 · 汤库（129 碗，由用户提供的 5 份 JSON 合并去重而来）
 *
 * 这个文件只放数据，不放逻辑。整份被 registry 的 React.lazy 裹着，
 * 只有点开这个游戏才加载，不拖慢 App 启动——跟大富翁的卡库一个待遇。
 *
 * difficulty 是**这碗汤本身**的难度（简单/中等/困难/抽象），用来抽汤；
 * 跟游戏规则里的轻松/正常/严格（提问次数限制）是两回事，别混。
 *
 * bottom（汤底）和 keyElements 只在主持人那一侧使用，**绝对不能出现在给 TA 的
 * 提示词里**——一旦 TA 看过汤底，"一起猜"就变成了演戏。见 ai.ts 的分层注释。
 */

export type SoupDifficulty = '简单' | '中等' | '困难' | '抽象';

export interface Soup {
  id: string;
  title: string;
  difficulty: SoupDifficulty;
  /** 汤面：给所有人看的谜面。 */
  face: string;
  /** 汤底：完整真相。只给主持人。 */
  bottom: string;
  /** 关键情节点。主持人判定和评分的 40% 那一档靠它。只给主持人。 */
  keyElements: string[];
  /** 分级提示，越往后越接近答案。从 JSON 里现成读取，点提示**不花 API**。 */
  hints: string[];
  tags: string[];
}

/** 内容分级标签。设置页的过滤开关按它筛。 */
export const SOUP_CONTENT_TAGS = {
  red: '红汤',
  yellow: '黄汤',
} as const;

