    "bottom": "住户其实正在家中，却在电话里故意说自己还在路上，希望送餐员把餐点留在门口后离开。送餐员相信屋内无人，便在一楼电梯口放置“维修中”的牌子，试图让住户改走没有监控的楼梯。迟迟等不到人后，他开始怀疑电话里的话，查看电表并发现住宅仍在用电，于是确定屋里有人，继续在门外约3米处等待。因此，“3米”不是楼层高度，而是送餐员与房门之间始终没有改变的距离；住户并未误会，他确实一直没有离开。",
