    "title": "五毒",
    "difficulty": "困难",
    "face": "五个人在五个密闭的房间醒来。房间的门都被锁上，在他们的面前有一块透明的玻璃，透过这块玻璃，他们能看到有一具尸体倒在血泊之中。我被捆在一把凳子上。只要你在五分钟内用力摇一摇这把凳子，你就能离开。我…多疑之人终会死在名为信任的铁器之下。两个全是刺的按钮上写着“是”和“非”，选择“是”则四人通关；选择“非”则一人过关。我…痴愚之人终会死在无知的森林。一分钟就是十万块钱，我要发财了，我…贪婪之人终会死在欲望的海洋。只要理解原谅你的做法就行吗？对不起，我…。怨恨之人终会死在愤怒的火焰之中。请在你的四个手足之中选择一个切除。我…看来真的有圣人，我服气了。我挺起身子，站了起来，地上很滑我差点滑倒。好了我…傲慢之人终会埋在寂静的土壤之中。",
    "bottom": "前情提要：本汤是根据佛家的五毒，贪嗔痴慢疑来写的，当然还有一个人就是所谓的佛。为了方便大家看懂，我在汤底里就直接用贪嗔痴慢疑和佛来表示这六个人了。我是慢，看着眼前病危通知书我陷入了沉默。在生命的最后时刻，我开始学习佛法。我想看看在佛对我的评价。我发现原来在佛法的五毒里我被称“慢”，代表了藐视一切，我乃是罪恶之人。诚然这一次我依旧是藐视了佛法，在我看来所谓的佛有什么资格让我赎罪！我为我所在的地方创造了多少财富，我帮多少人脱离了苦境。我轻蔑地笑了，既然想让我赎罪，好啊！那我用我的方法，我倒要看看佛所谓的赎罪能否成功，我也要看看那些被称为佛的人是不是真正的佛。我找来了代表贪嗔痴疑的四人。最后精心挑选了一位“佛”，此人与我颇有渊源。将他们迷晕之后，我就装成尸体，躺在这个房间的最中央。每个房间里我都放了一个录音机来给他们赎罪的提示，我手里还有控制所有门跟开关的遥控器。为了增加趣味性，我将五毒的赎罪设计成金木水火土。我将象征着疑的人绑在一个凳子上，在他脑袋边五公分左右的地方，有一根铁刺。那把凳子其实很不牢固，要在五分钟内用力摇一摇这把椅子，他就能脱困。可他好像不相信我说的话，他什么也没有做。最后他被铁刺刺死了。我在象征着痴的人的设计了两个按钮。“是”这个按钮上只有木刺。而在“非”这个按钮上的木刺，我已经涂满了毒药。如果他识相地选了“是”这个按钮，他顶多就受点皮外伤，我会立刻打开他的门。可他真是个蠢货，自己都被关着，还想要杀了我，真是蠢的让人发笑。最后他毒发身亡。我往象征着贪的人的房间里不断注水。开始之前，我用录音告诉他，只要他憋气一分钟就能获得十万块钱。如果选择放弃，他可以按墙上这个按钮，我会放他离开。可他被钱财蒙蔽了。最后他被淹死了。我把象征着嗔的人，放到了一个充满汽油的房间里。在这个房间的地板上，我布置了一个遥控火机。我用录音告诉他，只要他理解并原谅我的做法，我就会放他离开，可他张口就骂我。哼，死到临头了只有嘴是硬的。我按下按钮，他的房间瞬间成了一片火海。最后，作为佛的考验，我将他妻子父母四个人的照片挂在墙上，并给了他一把刀。只要他选择一个或者割下自己的一个手和足，他就能离开。他是最出乎我意料的，他真的把自己的手割了下来。最后我打开了他的门，我也站了起来。四目相对，相顾无言，最后他倒在了血泊之中。此刻有一点别样的心思，在我的心里产生了，是敬佩。可那仅存的一点敬佩，很快就被我的傲慢吞噬了。我发现我的赎罪也没有成功。最后我摁下了最后一个按钮，一声巨大的爆炸声传来。我和其他五人都埋在了寂静的土壤里。\n\n彩蛋：这是一个将死之人死前的一场赎罪测试，当你看到这些内容的时候。我可能已经被埋在冰冷的土壤之中了。你可能会问我的名字，但不好意思你还没有资格知道这些。但在那些狗屁佛家眼里，我就是慢，代表着傲慢与不屑。那就这么就叫我吧。在我很小的时候，我发现身边的人基本都跟不上我的思维模式，换句话说我的天赋无人能敌。在我结束学校的生活之后，我用了短短的十年控制了整座城市的经济命脉。那些所谓的政客商人都要对我客客气气的，这让我很满足。那些人就像我养的狗一样向我不断摇尾巴献殷勤，这些人没有一个可以有资格跟我平起平坐的。可好景不长，在我眼前的也只有一张薄薄的病危通知书，原来天赋是有代价的。我的时间不长了，在下属的安排下我住进了本市最好的医院。这些医院的护士都毛手毛脚的，根本就没有服务我的资格。我按了按床边的呼叫玲，等护士帮我翻身的时候我直接掰断了她的手指。她尖叫着骂着我是疯子，可那又怎样呢？我从柜子里甩出一大笔钱，丢在他的脸上，拿出电话跟院长报了这个护士的名字和工号，让她明天不用来上班了。我的动静马上迎来了我的主治医师，他跟我年纪相仿。他拥有着美满的家庭，跟大家都关系都很好，并且医术高明，被病人们称为在世的佛祖。“先生，你要相信我们医院，您的病情绝对会有转机的。”你们能拿出什么筹码能让我相信吗？我看着今天早上送来的报纸，连头都没抬一下。“先生，我现在很能理解您的心情，但是我并不认为这是解决问题的方法。”“是吗？可我就想这么做，好了你可以滚出去了。”接下来的日子里，我一边研究所谓的佛法，一边听这个单纯而又善良的医生讲述生命的美好，让我不要放弃。他的一次又一次坚持，让我觉得他跟佛真的很像。在他再一次来的时候，我问了他一个问题：如果用你自己的命换四个人活，你会选择牺牲自己吗？我没想到他毫不犹豫地回答了“会”。这一次，我第一次抬头看了他，好像他作为佛祖也算合格。至于剩下几个毒，在这个充满愚昧跟罪恶的城市里比比皆是。",
