    "face": "1：我司正在长期招收工作人员，高学历和高颜值的大学生优先，当然我们也绅士地保留了女士优先这个传统。2：我们的待遇非常好，我们会和每个工作人员签订劳动合同以便他们拿到丰厚的工资。3：我们很注重员工的身心健康，为此我们每隔一段时间就会请医生来检查员工的身体状况。4：我们公司的其他工作人员比如说门卫和清洁工，他们也都很尽心尽责，确保正式工作人员的工作环境。5：公司的设施十分齐全，公司内部甚至有专门供员工中午休息的床。6：我们的具体工作很好上手，并且每一位新来的员工都会有专业的指导人员来具体教学工作内容7：我们的工作具有一定的私密性，为了保护客户的隐私，请不要外传我们的工作内容。8：如果你在工作上出现失误，后果请自负。我们公司周边十分便利，菜市场，超市都有，尤其是首饰店希望我们的女性朋友能喜欢",
    "bottom": "这一份所谓的招聘公告，其实是非法招收代孕人员的窝点。很多雇主对于代孕者的要求很高，高学历和高颜值成了加分项。他们抛出丰厚酬劳这个饵，来引诱那些需要钱的女性来签订所谓的合同，事实上她们代孕之后拿到的钱只有一点点。他们每一段时间就会请医生来进行接生，并且医生会检查代孕者的身体是否还适合继续生育，从而来确定价格。公司的清洁工需要每天清洁来消除空气中的异味跟血腥味。安保人员的存在就是为了不让任何一个人跑出去揭发他们。公司内部的设施包括手术室，停尸间等一系列为代孕服务的设施。公司所谓内部的床就是代孕者们的休息地方，非常简陋。每一个代孕者来到这里都会直接有医生来进行取卵子的手术，整个过程只需要躺在手术床上，至于痛不痛没人会管的。每一个代孕者都没有自由，是不能泄露这个地方的任何信息。一旦出现泄露的风险，他们会直接杀死那个潜在的威胁。如果代孕者身体有什么问题，他们也会解决掉。他们会将死掉的人肉当成别的肉出售，首饰店里有很多人体组织做成的东西。比如说：人牙项链，骨灰烧成的钻石，骨头耳钉。",
    "keyElements": [
      "关键：是非法招收代孕人员的窝点",
      "关键：她们代孕之后拿到的钱只有一点点"
    ],
