    "title": "殡仪馆规则怪谈",
    "difficulty": "中等",
    "face": "规则1：欢迎来到沉渊市殡仪馆，本馆的宗旨是让您的亲友可以安详地离开，请您放心。规则2：本店有办VIP卡服务。有了VIP卡，我们可以给您提供一个专门的房间。规则3：要火化的尸体会发出刺激性酸味，请您带好口罩。规则4：当您看见尸体在轻微抖动的时候，请不要慌张，这可能是尸体肌肉松弛期的自发性抽搐行为规则5：当您看到身穿防护服的人时，请立刻远离。只有穿着普通白色衬衫的人才是我们的工作人员。请不要认错。规则6：当看见有人抱着骨灰盒十分兴奋的时候，请不要感到奇怪，这是他们对我们服务的认可。规则7：厕所里有很多灰，请不要诧异。这是那些烦闷的人抽烟而留下的烟灰。规则8：但您看见有人向你冲过来，请立刻离开，他们是本店的竞争者来搞破坏的。",
    "bottom": "沉渊市殡仪馆，实际核心是一个贩毒制毒场所。为了保证毒品原料的安全性，他们每隔一段时间就会安排一批人来殡仪馆到殡仪馆“火化”尸体。他们将那些尸体掏空，放入毒品原料，并用尸体原有的味道来掩盖。他们为了识别正常用户和瘾君子，毒贩们推出了VIP办卡服务。VIP卡的价格很高，只有那些吸毒的瘾君子才肯花这么多钱去办这么一张卡。有了卡之后可以凭借卡里的钱，买到毒品并且可以选择到一个专门的VIP室吸毒。除了普通的VIP办卡服务，他们对那些没有钱的瘾君子，有另一种换取毒品的方式。那些瘾君子可以将自己健康的亲友迷晕之后，伪装成要火化的尸体来殡仪馆换取毒品。毒贩们会把他们的亲友身体里的器官掏出，把器官卖出去后，这些尸体也可以作为下一次运原料的载体。这样他们就可以安详地离开了。当然了，有时候那些瘾君子掌控不好迷药的量，他们被迷晕的亲友可能会动一动。不过这可以用科学道理来解释，毕竟谁会想到要送去火化的尸体，其实是活的呢。那些身穿防护服的人是制毒师，他们绝对不会让自己的制毒秘方泄露，所以会规定要远离他们。而那些穿着普通白衬衫的人，才是真正贩卖毒品的毒贩。为了安全，毒贩们会将毒品放到骨灰盒，接着再给那些瘾君子。所以那些瘾君子抱着骨灰盒时才会十分兴奋。毒贩们将真正烧出来的骨灰放到厕所，并定期在旁边放上一些烟头，这样可以将那些骨灰伪造成烟灰。最后冲过来的人，其实就是警察，为了逃避抓捕，那些瘾君子就只能跑。",
    "keyElements": [
      "还原故事完整真相"
    ],
