    "difficulty": "困难",
    "face": "一个小女孩昏倒在了一家母婴店里，等到救护车赶来时，她已经没有了呼吸。由于没有女孩的身份信息，警察们只能通过走访查找线索。店员：“当时那个小女孩面黄肌瘦的，她一进来就拿了试用款，我一开始没觉得有什么。可她马上就开始呕吐并昏了过去。”一位路人：“这个好像是高高，不对也可能是兴兴，反正这俩姐妹好几天没见到了。”女孩的邻居：“警察先生我跟你说她们家那房子感觉就很阴森，晚上老是有黑影出现，之前一直有人往他们家里丢鸡蛋，现在还有臭鸡蛋的味道呢。”楼下菜店老板：“你说那个女人啊，我有印象，她的钱就跟她的人一样恶心，我都不想收。”警察找到了那个女人并进入了她的家，也发现了一切。",
    "bottom": "我是高高，我的妹妹叫兴兴。从我们记事起，我们的爸爸就不在了。我们饿的时候，妈妈总是给我们喝她那个罐子里的奶粉，那个奶粉有点怪味，而且喝了每次都肚子很疼。不过我喝了总会见到我们一家四口在游乐园里玩旋转木马，好幸福我每次都想多喝一点。可就在那天我好像喝的太多了，也许这样就能过我幻想的生活吧。我是兴兴，我看见姐姐昏倒了，可我好饿，我想喝奶粉。我走了很久找到了一家母婴店，我拿了一杯试用装奶粉，可我喝下去感觉肚子好难受，我开始呕吐不止，我的眼前一黑，再也没睁开过。我是林雾，是高高和兴兴的母亲，你也可以叫我毒虫。在我眼里高高和兴兴只不过是毒品交易的结果。当时我没有钱，我便身体来交换毒品。很快有人就说我是荡妇，高高兴兴是野种。每天都有人往我们家丢鸡蛋，整个家里都是臭鸡蛋味。那些邻居们每次都用鄙夷的眼神看我。不过我并不在乎，我只想要冰毒，为了掩人耳目，我将冰毒装入奶粉罐子。并且约定了晚上交易毒品，所以老是有黑影在我家附近。可我没想到高高和兴兴将冰毒真的当成奶粉了，她们跟我一样吸毒上了瘾。有一天我回家我发现高高躺在地上好像没有了呼吸，我并不想管她，我只想看看我的毒有没有少，“下贱的东西，又拿了我的毒品。”我抓着我的手臂，我已经等不及了。可这几天不知道怎么回事，给我供毒的人一直都没有来。高高的尸体也生了蛆虫，房子里到处都是蛆虫跟尸臭（就跟臭鸡蛋的味道一样）。我的肚子很饿，想去吃点东西，可我没有足够的钱，我在家里找了半天终于找到了几张爬满蛆虫的钱，下楼去买了一些菜，那个菜店的老板一脸的嫌弃，但他还是收下了。我上了楼，刚刚做完东西吃完饭，就听到了敲门声，我以为是毒品来了，我去打开了门。是警察，他们看见了高高的尸体，也发现了藏在罐头里的冰毒。",
