    "face": "我买了一个新手机，事业也得到了起色。（1）爸爸最近身体不好老是去拍x光片，他已经够糟心了，还是我自己解决吧。（2）谢谢你告诉我这些，我希望你能兑现你的承诺。（3）他是谁？“一只地下的老鼠，罪有应得罢了。”（4）我无法控制我的手脚，酸味是我最后闻到的味道。（5）队长，现场挺干净的，不过我们找到了这些东西，监控也拍到了脸，嫌疑人总共在楼道监控里出现了四次，可以进行抓捕了。（6）又在煮猪蹄啊，我跟你说你少放点醋。今天是你生日，你最近不是很爱画画吗，送你个画板还有这个新手机。还有就是快结束了。（7）本院支持原告的诉求，被告需要向原告赔偿xxx。（8）",
    "bottom": "在正式看汤底之前，请大家仔细阅读主持人手册。为了方便大家理解，先介绍一下本汤出现的人物：偷拍狂，被偷拍的女孩，女孩的父亲，女孩的男友和他的朋友（这个朋友不重要），许警官，高律师（他的妻子因被偷拍而被网暴，最终不堪受辱跳楼自杀），许sir跟高律师是很好的哥们。我是韩桐（被偷拍的女孩），最近我看到有人在跟踪我，我一开始不以为意。在第二天我发现我被偷拍了，而且照片被传到网上去了，虽然脸被打了码，但我还是能认出来。我的母亲早逝，是爸爸独自抚养我长大的。我不想让他再去承受这些事情了。于是我找到了我的男友，他是个网络高手，马上他就找到了那个把照片放出来的人，通过这条线找到了偷拍我的人，并教训了他一顿。我是韩旭，是女孩的父亲，那些偷拍我女儿的照片其实我也看到了。我很懊悔自己什么也做不了。但是这些事情直到一次体检之后都变了，我现在是肝癌晚期，活不了多久了。可几天之后，有位律师找到了我，他和我说了他的经历。并且告诉我只要我能把那个渣滓分尸了，他就会帮我女儿拿到一大笔赔偿金。我并不信任他，可我们的目的是一样的。这些天我天天去医院拍x光片是为了找到最完美的分尸位置。在那个男孩把那个渣滓弄晕的时候，我将他拖进我的房子里，一点一点把他的手脚全部切了下来。做完这些我也离开了，准备让他自生自灭。我姓许，叫我许sir就好，我和老高是多年的朋友。在我到现场时其实我对监控也有疑问，可这个案子破了我就能晋升。我也没有去管了。不过我还是将那份手机里的东西都复制了一份到新手机里，并时刻把它带在身上。直到我在老高生日的时候，我来看他，我闻到了满屋的猪蹄味跟白醋味，我就明白了第二个进入房间的人是老高。不过我并不想多事了，于是我把那个手机和我给他买的画板给了他。我姓高，是一名律师。在她死后，我的全名就已经不重要了。那个渣滓，我一定会找到你。经过多年的努力，我找到了当初的偷拍犯，而且我发现他还在进行偷拍。我对被偷拍的女孩做了调查，我决定从他的父亲入手，我查到他的父亲是肝癌晚期。于是我决定借他的手帮我除掉他。不过我还是要眼睁睁的看着他死亡。这些年我苦练画画，并且在老许帮助下得到了女孩父亲的照片。于是我煮了很多的猪蹄，用猪蹄的胶质制作了一个女孩父亲人皮面具。在女孩的父亲走后，我戴上面具，重新进入了房间，我用白醋一点一点的冲刷着血迹直到他的血流干了。我一开始并不想帮女孩申请赔偿，直到我看到了那个手机的内容。我发现那个偷拍狂，他家里最近拆迁分了1套学区房。用我的法律手段加上现有的证据完全可以让他的家人倾家荡产。当然，我伪装成一个正义的律师，拟了一份合同给那个女孩，让她在那个合同上自愿签下自己的名字。这样赔偿就基本都是我的了。",
