    "id": "soup_101",
    "title": "岛",
    "difficulty": "简单",
    "face": "后院的花现在开了。我回到了记忆中的地方。这里没有时间的迹象。晚上没来由的风治好了我的失眠。房子里还是挂着那些她收集的反季节物品。我小心地从房子里走出，也看到了那片花园。风停了，可岛还在。而我也明白了时间的含义。看来你已经好了。",
    "bottom": "我是一个三流作家，最近由于作品被举报再加上灵感枯竭，我患上了抑郁症和失眠。医生听了我的遭遇，说让我放下工作和手头上的电子产品去看看自然。外婆给我打电话说老家的花开了，想让我来看看。于是我来到了外婆家，那是在一个海岛上，是我从小长大的地方。外公前几年的时候去世了，外婆的身体也越来越差了，很多东西都记不清了。我和父母一直想让外婆住到城里，可她就是不愿意。不知道为什么家里的钟都坏了，我只能靠着太阳东升西落来判断时间。现在是夏天，可外婆还带着那个厚厚的手套让我很不理解。我本以为来到这里对我的失眠不会有好处，可每天晚上突然来的风，让我感到平静，我居然真的睡着了。早上起来，外婆还在睡觉。我小心地打开房门，为了不吵到她，我特意从后门走了出来，一出来我便看到了和小时候一样的花园。我呆住了，原来自从知道我要来外婆特意将花园布置的很之前一样。等外婆醒来后，我摘下了她的手套，是厚厚的老茧，我也终于明白了是外婆故意把家里的钟弄坏了。在她混沌的脑子里，这种方法能让我多留几天来好好治病。是她在晚上我看不到的地方给我默默地扇风；也是她将我梦幻的花园一点一点地重新建了起来。她也许忘记了很多东西，但她从没忘记过爱我。我把脸埋在外婆怀里，那片蓝布衫上还沾着灶间的烟火气，让人踏实。可眼泪偏不争气，先是鼻尖一酸，跟着喉咙就哽得发疼，像塞了团浸了水的棉花。过了一段时间我的状态好多了，可这座岛和外婆一直都在我心里。而我的病也不会再来了。",
