    "face": "我时常看见一个人，我一睡下他就出现在我梦里。不知道为何，我对他一见钟情了。在我醒来的日子里，我没有一天不在寻找他。终于我看到了“他”，我傻傻地笑着，“我要嫁给你！”我看着她，不知为何眼泪掉了下来。",
