    "id": "soup_103",
    "title": "门",
    "difficulty": "简单",
    "face": "“同学们，咱们现在升入高三了，我们需要紧张起来了。”砰，门像往常一样关上了，我躺着准备睡觉。砰，门像往常一样关上了，可我却睡不着了。我想了想写了关于门的日记。“孩他爸，听说最近晚上不太平。”“是吗？”那我……我终于睡着了。有一天，我头好痛又睡不着了，我开了门却看见了一个人。我的心好痛。我不再失眠了。",
