    "title": "贵宾",
    "difficulty": "简单",
    "face": "“警察同志，我家的宝宝丢了，你们一定要帮忙找一找呀。”“你先说明一下情况吧，我们好做部署。”一会儿警察们无语地看着我。我只好发布了启事：我家宝宝今年三岁，差不多40厘米高……酬谢1000元过了几天有个好心人找到了并归还了我的宝宝，而且他没有要报酬。连续几个月，宝宝老是走丢，不过总是被附近的流浪汉找回来。我也给了他们酬劳。“老宋，这人在人家门口晃了好久了，不像好人呀。走，过去看看。”我们抓到了他，是个流浪汉。他说了一切，我们没有说话，并把传达室里的纸箱子全给了他。如果不是人祸，谁愿意这样呢。",
    "bottom": "狗主人视角：我叫梅良心，为了在城市里买房。我逼迫父亲拿出来他这辈子的积蓄，我从小没有母亲，父亲很宠爱我。拿出了自己全部的钱，还把乡下的所有东西都卖了，给我在城里买了房子和车子。他做完这些之后，我觉得他也没有价值了。于是我就把他踢出家门，然后断了他每个月的生活费。为了显示生活的富足，我养了一条贵宾犬。我喜欢叫它宝宝，可是它总是喜欢乱跑。有一次它走丢了，这可是我花了好几万才买回来的。我慌忙地来到警察局报警，但他们听说我要找狗就一阵无语地看着我。幸好有好心人送回来了，他还没要报酬，世界上还是好人多呀。这几个月它越来越调皮了，老是走丢，幸好附近的流浪汉发现并归还了我，当然了我也给了他们报酬。这一次我要去长途旅行，以防万一我把狗带上了。流浪汉视角：我叫梅西望。在我把所有钱都给儿子的时候，他很高兴拉我喝了一顿酒。他喝醉之后，给了我一把钥匙说之后这个家里我随便进。我很天真地以为我之后能过上好日子了，可我想错了。第二天我就被赶出来了，他还把我的生活费也停了。我在农村的房子和地都没了，我什么都没有了，我只能乞讨当一个流浪汉。偶然的一次，我发现儿子在贴启事来找他的狗，而且是有报酬的。我萌生了偷狗的想法。隔一段时间我都偷偷潜入儿子的家里，把狗偷出来，最后再让同行去领取赏钱。可是这一次我被两个保安抓住了。我只能和他们说了真相，他们没有说话，只是把自己准备拿来卖钱的纸箱子给了我。",
