    "title": "镜",
    "difficulty": "中等",
    "face": "我的眼前一片漆黑，只是感觉有人在照顾我。我不知道照顾我的人是谁，我只知道今天是我和她见面的日子。有一天我看见了光，可那个人却不在了。我看见了她的样子，也听到了她的一切。",
    "bottom": "我有一个网恋女友，我们聊的很投机，于是互相换了各自的照片，经过一段时间的聊天，我发现她跟我在同一座城市。有一天，我突然想到约她出来线下见面，她也同意了我的想法。可就在那天，我在去见她的路上发生了车祸，视网膜损伤导致我失明了。她那天在我们约定的餐厅里等了很久很久，直到抬头看到电视上的新闻。她看到了我倒在车祸的血泊之中，于是她拿着我给她的照片在医院里找到了我。之后的每一天她都会来照顾我，我虽然看不见她的样子，可她带给了我亲人的温暖。大概过了一个月，我进行了一次手术，之后我的眼睛好了。我见到光明的第一件事就是去找她，可我找了好几天都没有找到。几天后，我收到了一个葬礼邀请，上面写着“让我见见你吧”。我马上赶到了葬礼现场，在那里我见到了一个准备火化的女孩尸体。这位女孩的母亲告诉了我一切，这个女孩是就是我的网恋对象，她在跟我网恋的时候就已经诊断出是肝癌晚期，没有多长时间了。之所以来照顾我，据她说：我是她在生命的最后时间里见到的一缕阳光。在她生命的最后时刻，她把眼角膜给了我，她希望我能再看到光明。在我重见光明之后，她不想让我见到她现在的样子，于是默默消失在了我的生活中，只给我留下了那一份葬礼邀请。ps：在这个故事的设定里男主我是一个孤儿，在这座陌生的城市里，我只有孤单一人。而女主年纪轻轻就被癌症所包围，也是苦命人，所以两个人才会更加珍惜对方。",
