    "id": "soup_107",
    "title": "屠",
    "difficulty": "中等",
    "face": "最近轰动全市的连环杀人犯已经在游乐园里被击毙。九位贵族小学的受害者已被救出，据他们说他们靠着自己带的干粮度过了这些天。这是最近失踪的一位女孩，知情的观众朋友们可以打电话给我们。游乐园里发生了火灾，据悉是电路老化导致的。最近我市的经济处于飞速上行阶段，之前大街上随处可见的乞丐现在都不见了，市容市貌得到了极大的提升。求求您，这是我们的全部身家！听上去像个不错的故事，我可以帮你招魂，不过得按我的方法来。",
    "bottom": "前情提要：汤底部分为作者的视角（也就是跟上帝视角一样）我的名字是……额好吧，我不知道我的名字，我来自冥界，负责人界的生死记录，说实话我很喜欢这份工作，因为我能看到人界光鲜外表下的丑恶。一般来说人的正常死亡我就简单记录一下，不过今天我在记录一个杀人犯和小女孩生死的时候，发现了一件有趣的事情。这个杀人犯在游乐园里制造了恐慌，导致了这十个孩子被困。其中的一个女孩是被一群小孩杀死，杀死她之后，身上的肉被那群小孩烤了吃了。在我记录的这么多年来，我还从来没见过小孩吃人肉。于是我开始默默关注这几个小孩。最后我发现了那群小孩和他们的父母好像对人肉上瘾了，怪不得最近消失了这么多的乞丐，敢情都是被他们吃了。这种事情我见多了之后，开始觉得没意思了。于是我将视角转到了小女孩一家。她的父母一直在寻找女孩的踪迹，他们发现女孩最后出现的地方就是那个游乐园。可是他们刚想继续去游乐园找女孩，结果游乐园发生了火灾。于是他们拿上了全部的身家，找了一位本市的私家侦探。这位侦探看着这么多钱，想都没想就答应了下来，可结果一连几天一点线索都没有。他哪里会知道，那群贵族小学的家长为了销毁所有可能存在的证据，连游乐园都能烧了，他还能找到什么线索。我看着他焦头烂额的样子，心里有了一个计划。我来到了他的面前，慌称我可以帮他，不过需要把他了解的事情跟我说一下。（虽然我早就知道了真相，但我还是想看看这个人调查到哪里了）他果然什么也不知道，于是我向他展示了我招魂的能力，他很高兴。其实他也差不多猜到小女孩应该是死了，于是让我来招小女孩的魂，让我来问她。可我怎么会听他的安排呢？我将小女孩的魂招到了她的身上，并打开了冥界和人界一道口子，随意找了几个灵魂给了他们线索，让他们来猜这个真相。不过受到我的限制，小女孩的灵魂只能回答是或不是，或者是也不是。我答应这些灵魂只要在灵魂存在的时间里猜出真相，我就会帮他们找几具人界的躯体，让他们重临人界。当然了，我是骗他们的。在他们猜的时间，我招来了杀人犯的灵魂，我要求他在九天的时间里把那个九个家庭的人全杀了。作为交换在女孩的灵魂存在时间结束之后，我可以把侦探的身体借给他。九天之后，他完成了我的任务，而我也亲手结束了这个渣滓的生命。",
