    "face": "一场车祸改变了我的一切，她就这样躺在床上。我会救你的，老婆。“先生，这是我们公司最新推出几种产品，包括我自己也在使用。”“我选那个最便宜的。”老婆醒来了，果然我们再也没有不开心过。可过了一段时间后，家里突然多了很多东西，老婆也常常跟别人介绍这些东西。我找到了他们，听了他们的话，我陷入了绝望。亲爱的，我们来生再见吧。我躺在了熟悉的病床上等待着末日的审判这位恐怖分子极其嚣张，在凶案现场甚至还详细地介绍了自己手上的武器。我是汉克，那一场车祸改变了我的一生。在那场车祸里，我的老婆成为了植物人，我用了很多办法都无法让她正常醒来。直到这天，我看到了一个名为情绪人生的广告。他们公司的最新产品可以将病人的脑部数据上传到他们公司的云端服务器，之后将脑子坏死的部分切除，制作一个代替的接受端放入大脑。虽然我没有看懂，但这是我唯一的方法了。我找到了他们公司的销售，令我感到奇怪的是他们推出的产品有好几种价位。由于没有钱了，我只能选最便宜的那个。选完了之后，他们马上安排了手术，我的老婆也马上醒来了。并且公司还给我手机里装了一个APP，这个APP上可以自由地调节老婆的情绪，我自然将心情愉悦值调到了最大。跟我想的一样，老婆每天都很开心。可过了一段时间后，我发现了一件奇怪的事。老婆总是会买一些乱七八糟的产品，而且总是莫名其妙地就冒出几句广告词。这让我们的生活出现了很多不便。我找到了那家公司，可他们的说法是我买的只是平民版，如果要去除广告，需要以月份来购买尊贵版。听完之后我马上明白了这是资本的陷阱，但我不得不跳。苦苦撑了几个月后，我再也撑不下去了。我将老婆的情绪值调到最低，用枕头捂住了她的头。她没有悲伤，没有反抗，只是下意识用手抚摸着我的脸。在这个时刻，科技没有限制她的情感。她走了之后，再也没有东西可以限制我了，这些存在于世界上的垃圾也应该要清理了。我借来了一笔钱，也购买了那件产品，并马上做了手术。做完之后，我将自己的情绪值调到最低。现在的我已经成为了冷血的鲨人狂了。我买了一支枪，冲到那个无良公司里开始无差别鲨人。那些人惊恐的表情并没有让我产生怜悯，可很快廉价产品的副作用开始表现，我开始不自觉地介绍我手中的武器。最后，赶来的警员趁我说广告词的时候，马上开枪击倒了我。如果有来生，我们还会再见的，对吗？",
    "bottom": "我是汉克，那一场车祸改变了我的一生。在那场车祸里，我的老婆成为了植物人，我用了很多办法都无法让她正常醒来。直到这天，我看到了一个名为情绪人生的广告。他们公司的最新产品可以将病人的脑部数据上传到他们公司的云端服务器，之后将脑子坏死的部分切除，制作一个代替的接受端放入大脑。虽然我没有看懂，但这是我唯一的方法了。我找到了他们公司的销售，令我感到奇怪的是他们推出的产品有好几种价位。由于没有钱了，我只能选最便宜的那个。选完了之后，他们马上安排了手术，我的老婆也马上醒来了。并且公司还给我手机里装了一个APP，这个APP上可以自由地调节老婆的情绪，我自然将心情愉悦值调到了最大。跟我想的一样，老婆每天都很开心。可过了一段时间后，我发现了一件奇怪的事。老婆总是会买一些乱七八糟的产品，而且总是莫名其妙地就冒出几句广告词。这让我们的生活出现了很多不便。我找到了那家公司，可他们的说法是我买的只是平民版，如果要去除广告，需要以月份来购买尊贵版。听完之后我马上明白了这是资本的陷阱，但我不得不跳。苦苦撑了几个月后，我再也撑不下去了。我将老婆的情绪值调到最低，用枕头捂住了她的头。她没有悲伤，没有反抗，只是下意识用手抚摸着我的脸。在这个时刻，科技没有限制她的情感。她走了之后，再也没有东西可以限制我了，这些存在于世界上的垃圾也应该要清理了。我借来了一笔钱，也购买了那件产品，并马上做了手术。做完之后，我将自己的情绪值调到最低。现在的我已经成为了冷血的鲨人狂了。我买了一支枪，冲到那个无良公司里开始无差别鲨人。那些人惊恐的表情并没有让我产生怜悯，可很快廉价产品的副作用开始表现，我开始不自觉地介绍我手中的武器。最后，赶来的警员趁我说广告词的时候，马上开枪击倒了我。如果有来生，我们还会再见的，对吗？",
