    "id": "soup_110",
    "title": "我",
    "difficulty": "简单",
    "face": "我成功了，放心，我会带来他们的成果醒来后，我看到了一个脸上缠着绷带的人弹片和鲜血随处可见我成功了，放心，我会帮助他醒来后，我见到了他我们赢了，现在它该毁了，我们也该走了。为什么？什么都没变",
    "bottom": "在开始之前，请大家注意一下前言。预测和重生其实就是穿越时空，一个是向后穿越，一个是向前穿越。因为这两个东西太吸引人了，所以会引发人们不断尝试。（ps本汤的时光机最多只能穿越十年）25岁的我（过去）：我是一个天才学者，在我25岁的时候，我发明了这个世界上的第一个时光机。那时人们还觉得这是一个好消息。作为发明者，我成为了第一个使用这个时光机的人。我的想法很简单，带回未来的科技，让现在的我们提前享受未来的生活。一阵眩晕过后，我看到了一个脸上满是绷带的人。我有点害怕，可他告诉我，他就是这个时间的我。35的我（现在）：由于十年前时光机的发明，导致有很多恐怖分子运用时光机来到未来，并将未来的科技运用于现在的战争之中。导致这十年间战乱不断。而我受到战争的波及，导致我毁容了。所以为了弥补我的过错，我决定要将战争结束在这一年。我的计划是等十年前的我穿越过来，让他自己看看现在的世界。从而回去之后就能毁掉时光机，这样战争就不会发生了。45岁的我（未来）：战争刚刚结束。这一场战争打了二十年，在复盘整个战争的时候。各国领导人一致认为是因为我的时光机而导致战争的发生。为了弥补我的过错，我再次制造了时光机，准备回到十年前也就是战争最激烈的时候。我想为当时的政府带去我们现在的科技，从而让战争快速结束掉。在我醒来时，我看到了他们两个人。我向他们说了我的计划，而现在的我（35岁的我）也说了他的计划。于是我们分头行动，他们两个准备时光机的自毁程序，而我去给现在的政府提供未来的技术。结束之后，我们看到了政府联军一次又一次的胜利。我们三个认为战争将会提前结束，于是我们启动了时光机的自毁程序，而过去和未来的我也消失了。现在的我：我自信等待着旁边的一切发生改变，可什么都没变。战争仍在继续，不知道为什么敌人的进攻又变得猛烈了。我无助地看着眼前的尸山血海。原来是这样，我明白了。这一场持续二十年的战争是必然发生的，而我的时光机就像一个骗局。它只不过在时代的浪潮里激起了一个小水花，不会改变时代的大趋势。作者的话：时间是公平的，该发生的事情是不会变的。",
