    "id": "soup_111",
    "title": "命",
    "difficulty": "困难",
    "face": "我感觉到了。又是一个有关夫妻问题的委托。一个化学家为了研究，而搬出去住很正常吧。话说他祖父是炼金术师，现在他是化学家也算传承了。我来到了那里，是一个孤零零的郊外房子。来的路上人们都说他是又瘦又臭。可他之前的照片明明很胖啊。开门的人穿的很严实还戴着口罩，应该是他的助理，他助理倒是挺胖的。好像没有什么问题。他还留我下来吃饭，不过他煎的牛排被他助理不小心打翻了。我看到了墙上的照片，他解释说这是祖父的老宅，并开始和我聊起他的祖父……他对他祖父居然这么了解。几天后郊外突然发生了火灾，很多人被烧死了。这张照片绝对不能流露出去。我什么都不缺了。",
    "bottom": "祂的视角：他是鲍斯，偶然之间他发现了他祖父的笔记，他祖父曾经是一个炼金术师。笔记之中描写了很多现代化学解释不了的东西。他一边在怀疑所谓笔记的真假，另一边对于知识的渴望，让他开始做起笔记上的实验。这些知识都是我留下来的污染，在他前几次实验成功之后，他将会疯狂地追求之后的终极实验。在笔记的最后一页，是历代人类所追求的实验：永生。他发了疯似的做了这一次实验，而他也将陷入深渊。这一个实验需要大量的生肉和尸体，他按照笔记上的记录制作出了一个怪物，他的脸上身上满是缝合的线，他似乎没有灵魂。可当他做完最后一步时，他身上的肉和大量尸体转变为了一个远古时期的灵魂，正是他祖父（鲍恩）的灵魂。由于鲍斯献祭了他的一部分身体，于是他很轻松地抢占了鲍斯的身体。而鲍斯的灵魂只能呆在那具怪物的尸体里了。鲍恩看着自己的身体，感叹着我的强大。他跪了下来，感谢我的恩赐，他感觉到了我的存在。鲍斯的妻子很快发现了丈夫的不对劲，于是派了一个侦探来调查他。当然，我相信鲍恩可以应对。由于需要大量尸体和生肉来继续对我给予知识的研究，鲍恩的身上总是很臭。他现在有了智慧和生命，他就开始渴望更强的力量，所以他就一定会继续研究我给予的知识。侦探来了之后，鲍斯去开了门，见到了另外的人，他迫切地想要开口告诉我他的处境和真相。可他现在的身体嘴是被缝上的。侦探当然没有发现什么。鲍恩正好缺少一个鲜活的实验体，于是他弄了一份生的牛排，只要他尝一口，他就会成为下一个实验品。可惜有着鲍斯这个变数，鲍斯故意碰倒了牛排让他的计划失败了。鲍恩的脸上出现了一闪而过的杀意。不过这个侦探并没有意识到。鲍恩主动和侦探聊起自己的事迹让他逐渐放下了戒心。几天之后，鲍恩的研究有了效果，他现在获得了力量。而鲍斯也没有了用处，于是他将鲍斯绑在房子里，一把火把这个房子烧了。碰巧的是，鲍恩满是缝合的身体居然还剩下了一部分，可这张满是缝合线身体的照片已经够让这个世界的警察头疼了。所以他们不会让这件事继续发酵下去的。而鲍恩为这场研究最大赢家，他作为人类确实什么都不缺了。",
