    "id": "soup_112",
    "title": "惧命",
    "difficulty": "困难",
    "face": "面对这件事时，我们会慌乱，我们这么做可以让大家以后轻松面对这件事。先生，有什么想去做的就去做吧。我无法做到，身后的一切还需要有我。你好结……账，商场监控显示屏里出现的家伙让我一愣。这么快，也许我该买那块以前舍不得吃的那块巧克力的……命运就是如此，先给你希望，再给你绝望。这一次他用一个玩笑带走了两个人的一生。",
    "bottom": "前情提要：真人秀节目的导演的名字是利弗，男主的名字是亚姆。利弗在小时候就经历了失去父母的伤痛，亲人的突然离去让他不得不改变自己原本的规划与计划。在他长大之后，他决定制作一档真人秀。简单来说，就是随意挑选一个普通人，让他见到所谓的死神。结束录制之后，在告诉他死神是假的，希望他能够珍惜当下，并给予一系列的奖金作为赔偿。亚姆在一年前就被诊断为癌症，医生根据检查的情况预估他只能再活最后的一年了。可他不能倒下，家里的一切还需要他，他只能更加拼命地工作，他希望在离开之前能给他们留下一些积蓄。这天他在超市购物，结账时他不经意地看了一眼监控显示屏。在他身后有一个拿着镰刀戴着黑色兜帽的家伙。他下意识地转头看去，可什么也没有。再次回头，他释然了。一年之前我就知道这一天会到来，我总以为我已经做足了准备，可真正面对时，我才发现我有多么可笑。也许，我该买那块平常舍不得吃的巧克力的。这时节目组看着眼前之人的表情发现不太对，导演赶紧从暗处跑了出来，告诉他没有所谓的死神，一切只不过是节目而已。得知了他的经历，为了表示自己的歉意，导演决定帮他支付后期的治疗费用。再次检查的时候，他们惊喜地发现，那天是医生误诊了。所有人都很开心，大家都在为亚姆的新生作庆祝。可不久之后，命运开了一个玩笑。亚姆出了车祸，抢救无效死亡了。而利弗得知这个消息之后，将节目雪藏了起来，并辞去了导演的工作。那天之后他便一直郁郁寡欢的，可能在他心里，他已经和亚姆一起离去了。",
