    "id": "soup_113",
    "title": "石",
    "difficulty": "困难",
    "face": "做生意的人都喜欢在桌上放一块石头。我的生意遇到了一些麻烦。我拜了码头，认识了徐总。名为金钱的石头被放在了桌上。名为靠山的石头被放在了桌上。名为贪心的石头被放在了桌上。名为忠心的石头被放在了桌上。我是李钰，是一个生意人。从小我的家庭条件就不太好，因为没有钱，我的童年都在寒风跟嘲笑中度过。这时我在心里暗暗下定决心，我要赚到很多钱，让那些嘲笑我的人都臣服在我的脚下。长大之后我抓住了一线机缘，终于成为了一名所谓的生意人。刚开始因为我的头脑，我赚到了一些钱，可很快遭到了他人的眼红。我初来乍到，没有靠山，没有人脉，靠我自己只能是处处碰壁，受到同行的打压。这天我的店里出现了很多小混混来闹事，我报了警，可第二天还会出现来闹事的人。这时我明白了这是同行干的，他们眼馋我的生意。我不甘心就这样被打压下去。我花了很多钱拜了当地的码头，并认识了当地商会的主席：徐总。我了解到徐总喜欢玉石，于是花大价钱给他买了一块石头，并承诺之后我的利润和他五五分。他同意了我的请求，第二天我的桌上出现了一块石头，我不明所以，拿起来看了看。仔细看了看才发现，这不是石头，是一块人骨头。我下意识地扔在一旁，心里感到后怕。可我的生意从我收到石头的那天开始，便开始顺风顺水。我渐渐地也明白了这是谁的骨头。过了许多年，我的贪欲逐渐膨胀，渐渐地我不再满足于一半的利润。我想吞下徐总的生意，我开始计划起来，这么多年了，我也有了自己的势力。我杀了徐总的一个心腹，并把他的头骨做成了一块特殊的石头。借过节的时候送给了徐总，他是个聪明人，应该知道我的意思了。送石头是我亲自去送的，他的办公室里还有一个年轻人。在这个年轻人身上，我好像看到了自己的影子，可又有点不一样。我那天晚上，我坐车回去的路上被一辆车撞了。当我醒来的时候，我的手脚都被绑着。眼前的人是白天的那位年轻人，自此我知道了我们不一样的地方。我最后变成了名为忠心的石头。“石头只是不会说话的人而已，石头很多，人也很多。”徐总看着眼前的石头说着，“年轻人，李钰的生意你可以接手了。”",
    "bottom": "我是李钰，是一个生意人。从小我的家庭条件就不太好，因为没有钱，我的童年都在寒风跟嘲笑中度过。这时我在心里暗暗下定决心，我要赚到很多钱，让那些嘲笑我的人都臣服在我的脚下。长大之后我抓住了一线机缘，终于成为了一名所谓的生意人。刚开始因为我的头脑，我赚到了一些钱，可很快遭到了他人的眼红。我初来乍到，没有靠山，没有人脉，靠我自己只能是处处碰壁，受到同行的打压。这天我的店里出现了很多小混混来闹事，我报了警，可第二天还会出现来闹事的人。这时我明白了这是同行干的，他们眼馋我的生意。我不甘心就这样被打压下去。我花了很多钱拜了当地的码头，并认识了当地商会的主席：徐总。我了解到徐总喜欢玉石，于是花大价钱给他买了一块石头，并承诺之后我的利润和他五五分。他同意了我的请求，第二天我的桌上出现了一块石头，我不明所以，拿起来看了看。仔细看了看才发现，这不是石头，是一块人骨头。我下意识地扔在一旁，心里感到后怕。可我的生意从我收到石头的那天开始，便开始顺风顺水。我渐渐地也明白了这是谁的骨头。过了许多年，我的贪欲逐渐膨胀，渐渐地我不再满足于一半的利润。我想吞下徐总的生意，我开始计划起来，这么多年了，我也有了自己的势力。我杀了徐总的一个心腹，并把他的头骨做成了一块特殊的石头。借过节的时候送给了徐总，他是个聪明人，应该知道我的意思了。送石头是我亲自去送的，他的办公室里还有一个年轻人。在这个年轻人身上，我好像看到了自己的影子，可又有点不一样。我那天晚上，我坐车回去的路上被一辆车撞了。当我醒来的时候，我的手脚都被绑着。眼前的人是白天的那位年轻人，自此我知道了我们不一样的地方。我最后变成了名为忠心的石头。“石头只是不会说话的人而已，石头很多，人也很多。”徐总看着眼前的石头说着，“年轻人，李钰的生意你可以接手了。”",
