    "id": "soup_116",
    "title": "病",
    "difficulty": "中等",
    "face": "最近村子里通了自来水，好方便。很多人得了病，身子开始凋零。我会找到药的。我翻了许多山，不久后我找到了药。我逃了出来，可罪的枷锁印在了我的身上。我回来了。我们已经找到药了。看着家门，我跪了下来。这次的药来自墓碑之下。合作愉快。这山里充满了欢声笑语，就像以前一样。",
    "bottom": "当大家看到这段文字的时候，我已经死了，死在那群人的刀下，死在绝望和恐惧之下。时间推回到接自来水的第一天，这是噩梦的开始和源头。自从通了自来水之后，全村人开始大范围生病，这种病很奇怪。大家的身体开始逐渐衰老，我是村里的郎中，但我从来没见过这样奇怪的病，我们村与世隔绝，我想也许外面的世界会有办法的。我告别了村里的人，我也不知道过了多久，我看到了一座城市，那里有我从来没见过的东西，后来我才知道是我们村太落后了，连最基本的手机都没有，我们那边的人甚至不知道警察局和医院。我用尽最后一丝力气爬到了街上，我晕倒了，再醒来我躺在了一张白色的床上，我问旁边的人这是哪里。他们用不解的眼神看着我，告诉我这是医院，是治病的地方。我听到这些字之后两眼放光，知道我来对地方了。我向过来的医生打听我们村的怪病，他说很巧，这种病之前在城市里也有，最近这几天研发的特效药解决了这种病。当我想要一些时却被告知这些药很贵，不是我能买的起的。于是我萌生了一个大胆的想法，我趁着夜色拿走了很多药，尽管我被警方通缉了。但我还是逃了出来。可当我来到家门口时，却发现我的父母妻儿都不见了，看到后院挂满的骨头我便明白了。我抓着路过村民的衣领，咆哮道“他们怎么了。”得到的只是戏谑的微笑，“只有你们家不得病，谁知道你们家有啥特殊的，不过吃起来还怪香的，虽然病还是没好。”我自知敌不过全村的人，可心中的怒火不允许我什么都不做，你们不是喜欢吃吗，我让你们吃个够。我将墓碑里的尸体挖出来捣碎，一个一个做成汤药，给村子里每一个人准备了一碗，为了让他们信服，我第一个喝了下去，不知道是幸运还是什么，我直到最后一个人倒下我还活着。我在这空无一人的村里呆了很久，直到那两波人的到来。xx总合作愉快啊。xx博士你也辛苦了。当然他们也发现了我，这村里最后的一个活人。为了让我死个明白，他们向我讲述了整个过程。最开始染病的是城市里的人，他们研究所被下了死命令要马上研究出解药。正好有个自来水厂的老板也想向房地产发展。这位老板看中了我们村子的地，可我们软硬不吃，这时研究所出现了，两人一拍即合，自来水厂在接的自来水里放入病毒原体，而研究所的人好好观察一下这些得病的人。终于他们研究出了特效药，这个时间正是我到城里的前几天。他们本想让村里人自生自灭的，没想到我的出现加速了他们的灭亡，而现在人没了，该建新房了。这里建了新的房子，进了新的人就像以前一样。",
