    "id": "soup_117",
    "title": "她们",
    "difficulty": "简单",
    "face": "医生，我女儿最近很叛逆，我喋喋不休地跟着心理医生说着。家里永远只有我在打扫卫生，我永远在为她操心。她好像听不懂我说的话一样，天天和我吵架。她爸爸是个好人，只不过被她气走了，有他在我肯定不会这么生气了。我就不该生下她。血从门外渗了进来，医生开了门，我走了出去。我下意识要教训她，可却被医生拉住了。这才是你，别继续了好吗",
    "bottom": "我是一名资深的心理医生，但今天我所看见的依旧让我感到后怕。病人是一位14岁的女孩，她父母从小离异，她母亲也是那种很典型的中式家长。可当这个女孩开口时，我却发现她用童真的语气讲出了让我恐惧的事。她用母亲的口吻说着她女儿的叛逆。我马上判断出了她有着双重人格，主人格为女孩，副人格为她的母亲。现在是她的副人格在跟我说话，她的副人格将她真正的母亲当作是叛逆的女儿。根据她的描述我大概懂了她的经历，她从小父母离异，不过她父亲应该对她不错，所以在她的视角里是女儿（也就是真正的母亲）叛逆气走了丈夫。她的父亲走后，她的母亲也患上了轻度的抑郁，不愿意做家务活。此时女儿的母亲人格出现每天开始打扫卫生，并觉得是女儿（也就是真正母亲的错）。因为是母亲人格，所以这两个人一直会发生争吵。并在她们自己视角里，谁也没有错。突然门外有血流进，我意识到不对，马上打开门查看，是女儿的母亲听了里面女儿的话，抑郁症发作加上急火攻心，于是做了割腕的举动。我没想到女孩的母亲人格如此癫狂，都这样了第一反应是教训她。我马上拉出她，给她看了病历单，告诉她她才是女儿，她看到的女儿是她的母亲。这才是她，病房里我安慰着她，别再继续了好吗。",
