    "id": "soup_118",
    "title": "它",
    "difficulty": "中等",
    "face": "乘客们你们好，欢迎乘坐本次星际航班。我们将负责各位的安全。这是一段遗言：1：如果一个人突然不说话了，或者开始口齿不清了，请不要多管闲事，更不要看他。2：如果有人重复你的话，请马上掐住你的脖子。3：不要相信任何人，有些歧视是刻在骨子里的。4：人需要有奉献精神，前提是找对了。5：永远不要情绪低落。6：你之前没有见过这飞船上的任何人，所有的熟悉感都是假的。来自：博士，大叔，师生，空姐。这是一段忠告：1.请相信你遇到的人，他们会帮你摆脱困境。2.当遇到其他人时，要主动和他们交流，拉近距离3.趁年轻多出来旅行。来自…",
    "bottom": "它将会取代人类……它能不断学习周遭的一切并不断超越。在那座已经毁了的飞船上，谁也不知道发生了什么，只知道在废墟之中走出了一个满身是血的女人。救援人员在营救之时，也在感慨生命的顽强。可真是如此吗？“这具人类的身体用着真是不顺畅，尤其是要面对其他低等生命体，真是无趣，不过好处是我终于能自由走动了。”人类的语言对我来说异常简单，或许我可以颠倒黑白，让更多人成为我们。想到这里，它提笔写下来飞船上的事情。这是一趟星际航班，据说是不会有任何故障，可惜碰到我了。我的感官与人类不同，我是按照生物体中的能量（也就是人的心情）来判断夺舍目标的。心情低落的人更容易受到外界的干扰，更容易焦虑和不安。大概感知了一下，飞船里有一个绝佳的夺舍目标。我在外头疯狂地撞击飞船，让修理员不得不出来查看，当然他们不是我的目标，直到驾驶员出来查看的那一刻，我的计划才刚刚开始。对了简单介绍一下飞船成员吧，一位博士，一位大叔，一位女士，一对师生组合，还有一位女士负责安保（也就是常说的空姐）。这位女士似乎是心情不好来度假的，这位博士似乎有这么一丝焦虑，这位大叔纯纯为了休闲而来，这位师生看起来欢声笑语，实则已有矛盾出现。这位博士交际能力很强，很快就和大家打成一片，而现在我就要发挥了。我逼停了飞船让他们陷入了恐慌，而不出我所料这位女士执意要离开，在她准备离开时，我便出现进入了她的身体里。刚开始我与她原本的意识在搏斗，不过她马上就败下阵来。我跪在地上一动不动，嘴里嘀咕着人类的基础语言。飞船上的人都吓坏了。这位热心肠的博士马上前去查看，当他蹲下去看我的眼睛时，我的能力便开始发动。他会不自觉地重复我的话，他于我而言是一个免费的语言陪练，当我成功掌握人类语言之时，这个陪练的意义也就消失了。而他也成为了第一个可以栽赃陷害的人。他也因为我的控制，而无法动弹。我慢慢地站起身来，流利地说出了人类的语言，我直接将矛头指向了博士，指出他现在被外面的东西附身了，不然怎么解释现在的样子。之后我拿出了飞船的船票，大家相继也拿出了自己的船票，而在博士身上并没有任何一张船票。很显然，他不是正常途径进的飞船。大家下意识地远离了他，他的嘴还只是一张一张地发出一些断断续续的话。现在大家虽然确定了是他有问题，可谁去解决他又是一个问题。“您好，我记得您说过，有什么问题您都会解决的，对吧。”空姐强装镇定，不断喘着粗气，面对我们这些人她没有任何胜算。她想逃离却被那位大叔直接抓住。“我们是顾客，你们这些飞船上的工作人员应该有觉悟的，对吧。”她只能答应，随着舱门的打开，死亡人数加二。这位师生诞生了很大的矛盾，学生完全理解不了为什么要一个无辜的人来牺牲的，他们完全可以先把这人控制住，等到了安全地方在进行处理。读取了博士记忆的我开始分析他们的矛盾，得知了人类种族歧视的问题。这位学生的肤色与我们不同，也许是一个好的突破点。“非我族类，其心必异。”黑人从始至终都无法在关键做出关键判断，这也是我们为什么排斥他们。不单单是肤色，更是能力的问题。这一句话一出那位学生直接炸了，当然大叔和他的老师都死死地按住了他，在他们争执之时。我悄悄跑到了驾驶室里去，驾驶飞船进行紧急迫降，我穿上了最后一件救生服，而其他人全部消逝在了火光之中。我活着是为了更伟大的事业，人类于我而言不过蝼蚁，他们在危难时候的不理性思考造就了这一切。",
