    "title": "笔记",
    "difficulty": "困难",
    "face": "男孩捡到了一本黑色笔记本，样子很像动漫里的那本。他把它带回了家，桌上一片狼藉，饭碗都倒了，父母也不知道去哪里了。一片狼藉的桌子，和电视上放的惨状车祸新闻让他没有胃口吃饭。“让我来试试你是否灵验吧。”他写下了一个名字。第二天我照常来到学校，那个人并没有死。只不过脸色苍白了很多。“搞什么，都是骗小鬼的恶作剧吧。”他丢掉了笔记本。“奇怪了，今天讲台上放的花的颜色怎么变了……”",
    "bottom": "我是一本拥有灵智的笔记，和那部著名作品中的笔记不一样的是，我可以根据持有者现有的状态来改变我的状态，而且一旦我被丢弃所有人又都可以看见我。简单点来说就是在我无主之时人和鬼都可以看见我，但当我的持有者是人的时候，只有人才能看见我，当我的持有者是鬼的时候，也只有鬼才能看见我。今天我被一个人类男孩捡了起来，他由于好奇写下了某人的名字。为了检验我的能力，他还亲自跟着那个人，直到他死于本子上的死法。他似乎吓坏了，丢下了我马上跑了。过了一会儿，一个鬼捡起了我，他把我带回了家。可怜的鬼到现在还不知道自己已经死了。事实上一片狼藉的餐桌是因为他父母听闻了他的死讯过于悲伤导致餐桌成为这样的，他们都来不及收拾餐桌就来到了他们儿子的死亡地点。这个鬼一边看着自己死亡的新闻，一边写着名字和死亡方式。第二天这个鬼和往常一样来到了学校发现那个人并没有死，很巧的是鬼写的名字正是那个害死他的人的名字，那个男孩正因昨天的惨状而脸色苍白。讲台上的花换成了白色，是为了祭奠死去的人。鬼还没有察觉到自己是鬼，也觉得我只是一个骗小孩的把戏，又是这样，我再一次被抛弃了。好了，现在谁会捡到我呢？",
