    "id": "soup_120",
    "title": "消失的租客",
    "difficulty": "困难",
    "face": "7月11日，我租到了房子，和我一起的还有我的四个室友。7月12日，房东来了，他人很好，丝毫没有说起房租的事情，第一次见面他送了我们他自己缝的衣服，他说这是他今年新做的，上面还有1990的生产日期。1月13日，这房子哪哪都好，就是没有邮箱，我们的社保金已经好久没收到过了。2月26日，我们接到报案，这房子里有奇怪的气味。我们砸开门冲了进去，发现只是地上的油漆没干。2月27日，又是同样的地方，只不过这次是房东报的案，说已经好久没有交过房租了。我们再次闯入发现油漆还是没干，我打破了地板。地板下藏有？具尸体，还有几张纸，还有几个空的胶布。2月28日，现场发现了很多针线，不知道是做什么用的。2月29日，我们仍然没有确定那具尸体的身份。迫于压力这具尸体也只能是他了。3月1日，最近的租房广告好多，都贴到我们这来了。",
    "bottom": "1990年7月11日，今天用低价房租忽悠来了五个傻子来看房，他们也许还不知道他们要经历什么。1990年7月12日，他们五个今天来看房了，五个移动的取款机，这些人的社保金可不少呢。我装出一副友好房东的样子，没有催促他们交房租，并给他们发了我今年缝好的衣服。事实上我并不是所谓的房东，我也是租客，现在高昂租金让我想到了这个方法，我自己就用他们每个月的保证金来生活。1991年1月13日，他们已经很久没有收到过社保金了，有人开始怀疑。既然怀疑了，那就把怀疑扼杀在摇篮里吧。我把这几个人都杀了，把他们放在地板下面，并在地板上涂满了油漆，掩盖尸体的味道。为了逃脱我的嫌疑，我想到了一个办法。我画了一副图，将人割为五份，这五份残缺的身体包含了头，因此我判定警察他们不会这么快就查出无头者的身份。做完这些之后，我将所有尸体用大胶纸全部粘了起来。这样就没看出缝合的迹象了。1991年2月26日，做完这些我便在房子周边订了个酒店来观察警察们的动向。第一次油漆未干而发出的气味让他们判断失误。1991年2月27日，这次是这座房子原来的房东过来了，我已经很久没交房租了，她叫来警察也正常。这一次警察发现了藏在地板下的6具尸体，用完的胶纸还有某个倒霉蛋的日记，现在看看他们能找到我吗？1991年2月28日，电视上公布了案件的细节和现场的照片，有我缝合尸体留下的线。1992年2月29日，已经过去一年了他们仍然没有找到我，也没有找到无头者的身份资料，大概这人是偷渡过来的吧。他们自然而然把无头者当成了我的尸体。1992年3月1日，我又干起了老本行，不过这次我要玩点刺激的。我来到了警局附近贴我的租房广告，就像1990那次一样。",
