    "title": "默义",
    "difficulty": "简单",
    "face": "我没有偷东西…她偷了。我没有偷。这是在狡辩？一万两年，两万一年，三万无罪，这是监控下明晃晃的交易。我没有偷东西我是不会承认的。请您帮帮她。我来到了她的面前，和她交流了一下，坚信她无罪的事实。也许这一刻我会得罪很多人，可我还是要做。她是一个聋哑人，某一天她被指控为一起盗窃案的嫌疑人。其他无辜的人可以直接说自己没有偷东西，并给上证据。可她只能用手语进行交流，警察叫来了手语翻译官。可出现了一个问题，就和我们方言是类似的，手语各个地区都不太一样。而警局的手语翻译官是用的官方手语，和她用的不一样。这就导致了翻译官听不懂，而他为了快点结案，便把手语的“我没有偷”翻译成了“我偷了”，毕竟这两个在手语上差不多。她听到翻译官的翻译，便请求写字，她写下了自己没有偷东西的事实。可警察却认为她在狡辩，于是她写字准备叫律师。可联系的那个律师是一个无良律师，他直接用她看的懂的手语表明了交易。给他一万块，被判两年；两万块，被判一年；三万块，直接无罪。她用手语表示她是不会妥协的，她没有偷东西。她的母亲找到了一个良心律师，求他帮忙。他听说了之后，和女孩交流了一下发现如她所说，她是无辜的。下一刻他和她站上法庭辩解，并讲出了手语翻译官的不负责任以及这条线上的黑心律师操作。而他也成为了万千聋哑人心中的光。",
