    "id": "soup_123",
    "title": "墙外",
    "difficulty": "困难",
    "face": "今天是我穿越的第一天，我要得到皇上的恩宠。这群贱人，她们是怎么想到这些方法的。居然有贱人想着逃跑，果然被侍卫处置了。为了能侍奉皇上，我开始接近他身边的太监。这太监色眯眯的眼神让我有点害怕。皇上只有晚上才有空，白天要上朝。皇上终于来了。宫门被打开了，是洋人打进来了，他们把我们都抓走了。我坐在洋人的汽车上，望着窗外的马路。我终于清醒了过来，看着眼前的一切我疯了。",
    "bottom": "最近接到检举，有一个贪官在郊外自己建了一个宫殿，我们马上集结队伍准备去一探究竟。结果发现那边所有的人都是古代服饰，这让我们非常奇怪。于是我们询问了这些人，得到了一个这座宫殿的所有。这座宫殿有着四种人，皇帝（贪官），侍卫（负责警戒的人），太监（那些和贪官有着合作的人或者是他的下属）最后的是宫女，这些宫女都是被抓来的失踪年轻女孩，她们先被集中送到一个地方进行洗脑让他们相信她们穿越了。现在是古代，他们穿越成了宫女只要讨好皇上就能走上巅峰。这些女孩因为看着电视剧里的宫斗现场，因此她们勾引的手段都如出一辙。当然也是有清醒的人想要逃走的，可结果就是被侍卫吃干抹净。而女孩太多，贪官的精力却有限，于是他就放任他的下属（太监）来享用这些女孩。而贪官仍需要保持自己的地位，所以白天的上班是不可避免的。不过他会在晚上随机宠幸一个女孩。当我冲进这所谓的宫殿时，这些女孩还以为我们是入侵的洋人，我们依法抓走了所有人。并给他们进行了心理辅导和治疗，终于她们清醒了过来。她们当中的有些人接受不了这个事实，当场就疯了。而那些丧心病狂的人也终于受到了法律的审判。",
