    "id": "soup_124",
    "title": "颜色",
    "difficulty": "困难",
    "face": "雨后天晴。今天是“老路”修房子的日子，除了某个人大家都准备来帮他。可“老路”说自己能行，我们便识趣地离开了。可第二天“老路”死了，我们最后看见的只有深深的指印。嫌疑人自然落在了那天没来的“贝尔”头上。当警察和我们赶到时，“贝尔”已经被打的身负重伤。“利维”平时总是说大家坏话，我们都开始下意识远离他，他沉默了许久也只能回去了。再见到“利维”之时，已是一具腐烂的尸体了。我们很害怕全部躲回了家中，只有“阿斯”不怕，准备去外面找刺激。“阿斯”被冻死了…“别西”跟我们说他这几天都不出门了，他有预感，他要做个饱死鬼。再见之时他的眼中只有落日的残光。只有我和“老玛”了，“老玛”说凶手是冲着钱来的，他要回去避免被抢劫。我成了最后的嫌疑人，见到的只有警戒线了。天的颜色变得好奇怪…我明白了颜色的含义天暗了…我是一位资深心理学博士，专攻催眠一类。今天要去精神病院给一个病人做精神治疗。出门时发现有七位家属跪在了我的诊室旁边。我连忙将他们都扶了起来，听他们讲述了一个令人触目惊心的故事。一个杀人犯杀了他们的孩子，结果在法庭上被他的律师以他有人格分裂为由，因此法院无法给他判刑。这些家属找上了我，希望可以让我帮帮忙。我问了这个案子的具体细节有了一个计划。当我来到他面前时我将他催眠了，并短暂地掌控了他的主人格暴怒（红色），还有其他人格贪婪（黄色），嫉妒（绿色），色欲（蓝色），傲慢（紫色），懒惰（青色），暴食（橙色）。由于我是精通心理学再加上我是主人格，我对他的心理世界有着绝对掌控，但我的目标是让他自己认罪，收到法律的制裁。我重新构建了他的心理世界，将其变为一个小镇。将一条彩虹贯穿了整个小镇，当我每杀死一个人格时，彩虹的颜色就会少一种。为了唤起他内心的恐惧，我将他的杀人手法全部复刻到杀死人格方法上。掐死傲慢，脸色发紫，紫色消失。将懒惰揍的浑身是淤青，青色消失。色欲被放入冷库内冻死，蓝色消失。暴食的眼睛被挖出白色的眼珠映衬着橙色的夕阳光，橙色消失。解决贪婪之后，我将暴怒人格还给了他，而他只能看见黄色的警戒线，黄色消失。而以上种种都是他原本的杀人手法。现在天空中只剩下红色，他不再是那个神经失常的人，意识到自己杀了七个人，那七个人的鬼魂似乎萦绕在他的身边，不断说着冤屈。“我该死。”不知何时，一把刀出现在他的脚边，正是我弄出来的。这把刀刺入了他的心脏，红色消失。天空只剩下了黑色。他睁开了眼，满眼泪水，“警官，我要坦白。”当说出这句话时，我明白了我成功了。",
    "bottom": "我是一位资深心理学博士，专攻催眠一类。今天要去精神病院给一个病人做精神治疗。出门时发现有七位家属跪在了我的诊室旁边。我连忙将他们都扶了起来，听他们讲述了一个令人触目惊心的故事。一个杀人犯杀了他们的孩子，结果在法庭上被他的律师以他有人格分裂为由，因此法院无法给他判刑。这些家属找上了我，希望可以让我帮帮忙。我问了这个案子的具体细节有了一个计划。当我来到他面前时我将他催眠了，并短暂地掌控了他的主人格暴怒（红色），还有其他人格贪婪（黄色），嫉妒（绿色），色欲（蓝色），傲慢（紫色），懒惰（青色），暴食（橙色）。由于我是精通心理学再加上我是主人格，我对他的心理世界有着绝对掌控，但我的目标是让他自己认罪，收到法律的制裁。我重新构建了他的心理世界，将其变为一个小镇。将一条彩虹贯穿了整个小镇，当我每杀死一个人格时，彩虹的颜色就会少一种。为了唤起他内心的恐惧，我将他的杀人手法全部复刻到杀死人格方法上。掐死傲慢，脸色发紫，紫色消失。将懒惰揍的浑身是淤青，青色消失。色欲被放入冷库内冻死，蓝色消失。暴食的眼睛被挖出白色的眼珠映衬着橙色的夕阳光，橙色消失。解决贪婪之后，我将暴怒人格还给了他，而他只能看见黄色的警戒线，黄色消失。而以上种种都是他原本的杀人手法。现在天空中只剩下红色，他不再是那个神经失常的人，意识到自己杀了七个人，那七个人的鬼魂似乎萦绕在他的身边，不断说着冤屈。“我该死。”不知何时，一把刀出现在他的脚边，正是我弄出来的。这把刀刺入了他的心脏，红色消失。天空只剩下了黑色。他睁开了眼，满眼泪水，“警官，我要坦白。”当说出这句话时，我明白了我成功了。",
