    "id": "soup_125",
    "title": "伦",
    "difficulty": "中等",
    "face": "最近发生了多起失踪案，失踪人口均为离异带孩女性。小孩子总喜欢去脏乱的地方玩。一只精致的手从水泥里伸出，吓坏了周围的孩子们。失踪人口都找到了。可她们的头似乎有点不太对劲。经过了几天的调查我们发现了一位女性，她家里有一个弟弟很符合嫌疑人的特征。这对姐弟相差了16岁。更奇怪的是他们的父亲在很早时就因车祸死了，这样的家庭为何还要收养这个男孩。我们找到他时，他正在用同样的方式埋葬她的“母亲”。我是本不该出现的人，她为什么要把我带到这个世界上。至于其他人，我只是想让她们都做一个模范妈妈罢了。",
    "bottom": "有些人本就不该出现在这个世界上，而我便是其中之一。我是洛比，是埋葬那些女人的凶手。可我只想让她们做一个模范妈妈。我从小没有见过我的父母，直到后来有一个女人收留了我，这是一个没有父亲的家庭，与之相对的我还有一个姐姐。我们就这样平平淡淡过了许多年，直到我成年之后我发现了姐姐的一些事情。出于青春期的孩子最强烈的就是欲望，尤其是对异性，这就导致了我身边的朋友几乎都和我姐姐睡过。为此他们还跟我炫耀他们的战绩。作为一个正常的青春期男孩，我非常渴望肉体的欢愉，我向姐姐提出了我大胆的想法，可她言辞犀利拒绝了我的想法。我不明白为什么她为什么不能接受我，畸形的感情让我想要强来。可没想到我的姐姐说出了一句让我三观崩碎的话，“你是我的儿子。”我顿时呆住了，原来我是姐姐16岁时生下来的。她之所以性欲强烈是因为小时候发生了车祸，她的父亲（也就是我的外公）死在了那场车祸里，而她也脑额叶受损从而性欲强烈。为了掩盖家族的丑闻，我的外婆将我收养成了儿子，对外声称为她女儿（我的母亲）收养了一个弟弟。强烈的反差感让我逐渐感到愤怒和不甘，我不敢相信眼前这个不检点的女人居然会是我的母亲。此刻母亲这个神圣不可侵犯的形象直接在我脑子里崩塌了。我用拳头一次又一次地锤着她的脑袋直到她的身体变得僵硬。做完这些后我缓缓地站了起来，我将尸体塞进一个铁桶中向里面灌满了水泥，只剩一只手露在外面。水泥和铁桶就像一个墓地一样，而露在外面的手就像一个小型的墓碑。我将这个桶随意地摆在垃圾场里，就和她本身一样，像一件需要处理的垃圾。之后的日子我开始将目标对准离异带娃的女性，我认为这些人都需要得到我的洗礼。而我独特的洗礼便是将她们的头骨切开，将她们的脑额叶切掉，这样她们也就不会有这样的欲望了。不过很明显的是，我的技术并不是很好，所以手术的成功率很低。不过没有关系，这些只不过是我要处理的垃圾罢了。越来越多的铁桶出现在了垃圾场。“母亲”（我的外婆）好久没有收到姐姐（我的母亲）的消息了。她以为和之前一样出去找男人了，就没有在意。可时间越拖越久，她感觉到了不对，终于她向我问了“姐姐”的去向。我望着眼前这个老女人，她为什么要收养我，如果她视而不见，我明明就可以活的很好。我将她砸晕了，准备用同样的方式送他上路。可来不及了，警察找上了门。而这些就是我的证词，我本就是一个不该出现在世界上的人，现在的离开也算正常。",
