    "difficulty": "中等",
    "face": "我看到了你，我抓着头，我不会让你得逞的。最近接了一个单，是个恐怖小说家犹葛的失踪案，这种案件有什么好调查的？而且连雇主的名字都没有。怎么还有人要杀我，真是奇怪。我看了看犹葛的小说，发现了一些线索，拼成了一张地图。可这地图的终点好像并不存在。在我开车经过地图上最后一个隧道时，我晕了过去。我来到了似曾相识的地方，凭着记忆我走进了一个房子。里面有哒哒哒的声音，接着一个男人出现了，将一样包裹给了我。我想要跑开，却发现我在原地踏步。我苏醒了过来，发现我在车里睡着了。那个包裹却还在我旁边，我惊恐地丢掉了它。并开车来到出版社。你说犹葛先生，正常是只有他的代理人能看到他的书，不过这次他早就把新书寄给我了。而且我没有委托过侦探啊。新小说非常火爆，几乎人人都看过。他们的样子都像是疯了。我打开了包裹，包裹的背面还有张字条。原来我早就被看见了。这个世界疯了，你也是。",
    "bottom": "我是犹葛，也是门之匙（犹格索托斯）在这个世界的代理人。由于这个世界意志对我能力的削减，我无法直接动用我的能力来入侵这个世界。于是我学习了这个世界的文字，我将部分精神污染的文字写在我的小说里。前面的小说只要有人看到就会受到精神蛊惑，具体表现为：疯狂追求我的小说。我还给我的小说起了一个代号，名为克苏鲁。前面的小说由于精神污染程度不高，所以我只需要一个普通的锚点来传播就可以。我选定了一个代理人，他会是一个看完我小说的人，他也是我在现在这个世界的第一个锚点。最后一本小说将具有一定的虚幻转变现实的能力，我在书中描写了现实存在的一个侦探，并用代理人这个锚点对他进行交互。只要让这个侦探看过小说，并且相信自己是小说里的人物，在这个时候他将成为另一个锚点。我的全部能力将会解锁。届时看过小说的所有人都会陷入疯狂，为此我设计了一个情节：先由我自己发布失踪案委托。之后让代理人看到我最后的小说情节发现了侦探会是污染这个世界的起源。他将会用自己最后一份理智来杀死侦探，当然他一定会失败，之后侦探会开始调查我。侦探会开始看我的小说，并从小说里找到我构建的小说世界入口。我将会在我构建的小说世界里把小说给他，并让他带回现实世界。由于我的权柄，小说世界跟现实世界时间流速不一样，事实上在他跑出小说世界的时候，小说已经发表在现实世界了。而在他醒来的时候，小说已经发表了。所以出版社老板才会说我早就拿给他我的新小说了。而在最后我将污染这个世界的过程写在了一张纸上，贴在那个包裹的后面，只要侦探看到真相，他就会相信他是小说中的人物，他早就被我们看见了。而这张纸我把它叫做汤底，作为污染下一个世界的媒介。而你，我的朋友。你能保证自己看完不会疯吗？对了还要介绍一下汤面作者的身份，他是这个世界门之匙的又一代理人，他于雾中长眠，只有在我的召唤之中才能苏醒。你们可以猜猜他的名字。",
