    "face": "血肉和弹片落在我旁边。0干掉他，拿到钱，好像很对。1你找不到他的。2要死在这里了吗？3一群废物。4不敢想我以后居然是这个样子的。5别贫嘴了，要来不及了。6你们失败了，什么都不会改变，不是吗？7",
    "bottom": "过去的口述（我20岁时）：20岁那年，我成为了时空管理局的杀手。我认为的时空管理局，是用大数据来预知未来可能发生的恐怖事件，并将组织这场恐怖事件的主要人物标记出来。最后在这个时代将主要组织者杀死，这样未来的恐怖事件就不会发生了。我一直认为我是在做正义的事情，直到那一次。这天我接到了一个杀人的任务，给了我他的照片和他所在的位置，是一个郊区的仓库。我没多想就马上过去了。可没有我的目标，只有那群时空管理局的人在，原来他们给我的照片是一个来自未来的人的照片，而他们的真正目的是杀了我。因为我是二十年后的政府反叛军首领。在枪口抵着我脑袋的时候，我看到了两个人影逆光而来，光把他们的影子拉的很长。不知道为什么，我总感觉他们两个很熟悉。其他时空管理局的人见到这两个人跟见到鬼了一样，纷纷都不敢上前。在一阵枪响之后，时空管理局的人全部死完了，只剩下我们三个，当他们拿出熟悉的烟的时候，我好像也猜到了什么。好了，现在是他们两个的自述。未来的口述（我四十岁时）：在30岁时，政府与底层人民的矛盾不断激化，于是我加入了政府反叛军，在40岁的时候我成为了头领。那群政府的走狗，拿我没有办法。于是将目光对准了十年之前，他们用最后的财富创造了一台时光机，准备穿越到十年前来对付我。我怕他们得逞，于是在他们走了之后，也使用了时光机一起穿越了过去。现在的口述（我三十岁时）：可他们小瞧了30岁，也就是十年前的我，我带领着一帮子人马上把他们打趴下了。剩下的人见状不妙赶紧跑了，我拷打了那些被我留下来的人，知道了他们的计划。同时在我面前出现了个意料之外的人物，看着他我总感觉熟悉，可又想不起来，当他说出他说出他是十年之后的我。他说了只有我自己才知道的秘密，我相信了他。他说那群人绝对不会罢休的，从俘虏的口中得知了时光机的位置，于是我们再次使用了时光机回到十年之前。在20岁的我快被枪毙之时，我们及时赶到，干掉了所有人。经过我们的推测，这些所谓的时空管理局对外的介绍只不过是蒙骗人的，他们的真实目的是为了将我招进来之后，将我杀死，从而在未来他们和他们的势力依旧能只手遮天。可他们没有想过，正是这一次的事件给我心里种下了种子。以至于我在未来的二十年里我会参加政府的反叛军，成为头领。如果他们能把我们当人一样看，也许未来会不一样。可在发生的事情已经发生，不会再次改变的。",
