    "title": "酒吧",
    "difficulty": "简单",
    "face": "欢迎来到xxx酒吧，我是这里的酒保兼职老板，接下来让我简单介绍一下。1.我们和平常酒吧的热闹的时间段不同。2.我们这里的服务人员都很热情，希望您喜欢。3.我们酒吧24小时营业，不同的时间有不同的惊喜。4.我们酒吧的位置很好找，方便大家过来。5.如果大家有落下东西，不要着急我们会替您保管好的。……1.我们正在寻找认真负责，积极向上的年轻人。2.我们团队的福利非常多，不仅有着更长时间的午休，还有着更高的工资，工作环境更是像家一样。3.我们的更高工资是为了大家更容易享受生活。4.公司非常注重时间观念，时间就是金钱嘛。公司不会开除员工，请大家放心。我是酒吧里的酒保兼职老板，不仅仅是这个酒吧，我更是楼上公司的老板。望着日益增多的离职人员，我在想如何能摆脱这个困境。刷着手机里的经济形势分析，他们说未来情绪消费是主要大头。我脑瓜一动，想到了一个点子，既然如此我在公司楼下，开一个酒吧，再把午休时间调长，再安排一两个人，每到午休时间就怂恿人去下面的酒吧。与平常的酒吧不一样的是，我将主要的消费群体定在了我们公司的人，因此我将这个酒吧叫做白日梦酒吧。意味着只有白天才能享受到高级的服务，而在晚上这就是一个普通的酒吧。我将白天的服务员全部换成肤白貌美的美女，跟他们承诺只要卖出去一瓶酒就能拿到很高的提成，并且只需要在白天上很短时间的班。这样的条件很快地吸引了不少人来应聘。毕竟谁不想要轻松钱又多的工作呢。为了吸引更多的韭菜来我这里工作，我专门贴了一份很人性化的招聘启事。不过我的目的可不像上面写的那样（接下来让我给你们解析一下一个资本家的套路）1.我需要大量的年轻人来为我工作。2.长时间的午休是为了让大家有时间能去楼下的酒吧消费，当然明面上的工资是挺多的，不过到手的可就不一定了。再者我在公司里放了能使人慵懒的香氛，这样会让人们下意识地放松警惕。3.看着预计能发下来的高工资以及我安插卧底的怂恿，越来越多人经不起诱惑，选择去一次就有第二次。4.我的公司很注重考勤制度，并且是以分钟作为罚款标准的，而且罚款非常多。因为午休时期有很多经不起诱惑的人在楼下酒吧放纵。因为酒精的麻痹和服务员的热情，让他们马上陷入了温柔乡，他们常常会迟到很久。这样长此以往，他们拿到手的工资甚至是负的。不过这并不能怪公司，谁让他们经不住诱惑，他们碍于面子也不会和别人说公司的不好。那些拿到负数工资的员工就是说欠了公司的钱，既然这样自然是用他们的时间来抵押，也就是加班。5.用这样的方法我将每一个员工都牢牢锁在了牢笼之中，他们唯一存在的价值就是给我赚钱，我也不会去主动开除他们，一是要给赔偿，二是完全没必要。你看现在又有韭菜上钩了，这个人在他人的怂恿之下，本来只想来喝杯饮料。可当他进入酒吧的那一刻，他就已经掉入了我的陷阱了。第一次他很拘谨也很谨慎，但是当美女服务员出现的那一刻，他所谓的谨慎完全就是一个笑话，他被怂恿地喝了一杯酒之后完完全全就陷入了温柔乡。不过毕竟是第一次，他马上反应过来还要上班，马上准备离开。可当他要走出门口的那一刻，我们的美女服务员叫住了他，把他掉的东西给他，并加上了自己的联系方式，好了现在他已经陷进去了。而第二天也正如我猜的那样，他在酒吧冲动消费了自己所有的积蓄，并在迟到了很久，我也是按照公司规定对他进行了处罚。他低着头，脸因酒精变红的样子真的很像一个囚犯，只不过不是监狱里的，而是在我所创造的囚牢之中。",
    "bottom": "我是酒吧里的酒保兼职老板，不仅仅是这个酒吧，我更是楼上公司的老板。望着日益增多的离职人员，我在想如何能摆脱这个困境。刷着手机里的经济形势分析，他们说未来情绪消费是主要大头。我脑瓜一动，想到了一个点子，既然如此我在公司楼下，开一个酒吧，再把午休时间调长，再安排一两个人，每到午休时间就怂恿人去下面的酒吧。与平常的酒吧不一样的是，我将主要的消费群体定在了我们公司的人，因此我将这个酒吧叫做白日梦酒吧。意味着只有白天才能享受到高级的服务，而在晚上这就是一个普通的酒吧。我将白天的服务员全部换成肤白貌美的美女，跟他们承诺只要卖出去一瓶酒就能拿到很高的提成，并且只需要在白天上很短时间的班。这样的条件很快地吸引了不少人来应聘。毕竟谁不想要轻松钱又多的工作呢。为了吸引更多的韭菜来我这里工作，我专门贴了一份很人性化的招聘启事。不过我的目的可不像上面写的那样（接下来让我给你们解析一下一个资本家的套路）1.我需要大量的年轻人来为我工作。2.长时间的午休是为了让大家有时间能去楼下的酒吧消费，当然明面上的工资是挺多的，不过到手的可就不一定了。再者我在公司里放了能使人慵懒的香氛，这样会让人们下意识地放松警惕。3.看着预计能发下来的高工资以及我安插卧底的怂恿，越来越多人经不起诱惑，选择去一次就有第二次。4.我的公司很注重考勤制度，并且是以分钟作为罚款标准的，而且罚款非常多。因为午休时期有很多经不起诱惑的人在楼下酒吧放纵。因为酒精的麻痹和服务员的热情，让他们马上陷入了温柔乡，他们常常会迟到很久。这样长此以往，他们拿到手的工资甚至是负的。不过这并不能怪公司，谁让他们经不住诱惑，他们碍于面子也不会和别人说公司的不好。那些拿到负数工资的员工就是说欠了公司的钱，既然这样自然是用他们的时间来抵押，也就是加班。5.用这样的方法我将每一个员工都牢牢锁在了牢笼之中，他们唯一存在的价值就是给我赚钱，我也不会去主动开除他们，一是要给赔偿，二是完全没必要。你看现在又有韭菜上钩了，这个人在他人的怂恿之下，本来只想来喝杯饮料。可当他进入酒吧的那一刻，他就已经掉入了我的陷阱了。第一次他很拘谨也很谨慎，但是当美女服务员出现的那一刻，他所谓的谨慎完全就是一个笑话，他被怂恿地喝了一杯酒之后完完全全就陷入了温柔乡。不过毕竟是第一次，他马上反应过来还要上班，马上准备离开。可当他要走出门口的那一刻，我们的美女服务员叫住了他，把他掉的东西给他，并加上了自己的联系方式，好了现在他已经陷进去了。而第二天也正如我猜的那样，他在酒吧冲动消费了自己所有的积蓄，并在迟到了很久，我也是按照公司规定对他进行了处罚。他低着头，脸因酒精变红的样子真的很像一个囚犯，只不过不是监狱里的，而是在我所创造的囚牢之中。",
